const responseBody = pm.response.json();

pm.test("Status code should be 200", function () {pm.response.to.have.status(200);});

pm.test("Response content type should be JSON", function () {const contentType = pm.response.headers.get("Content-Type");
    pm.expect(contentType).to.include("application/json");
});

pm.test("Response should contain a fact", function () {
    pm.expect(responseBody).to.have.property("fact");
    pm.expect(responseBody.fact).to.be.a("string");
    pm.expect(responseBody.fact).to.not.be.empty;
});

pm.test("Response should contain a numeric length", function () {
    pm.expect(responseBody.length).to.be.a("number");
});

pm.test("Fact length should match the length field", function () {
    pm.expect(responseBody.length).to.eql(responseBody.fact.length);
});

pm.test("Fact should respect the maximum length", function () {const maxLength = Number(pm.request.url.query.get("max_length"));

    pm.expect(responseBody.fact.length).to.be.at.most(maxLength);
});

const jsonData = pm.response.json();

const requestedLimit = Number(
    pm.request.url.query.get("limit")
);

const maxLength = Number(
    pm.request.url.query.get("max_length")
);

// Diagnostic: compare the API-reported length with JavaScript character counts
const diagnostics = jsonData.data.map((item, index) => ({
    record: index + 1,
    fact: item.fact,
    rawFact: JSON.stringify(item.fact),
    reportedLength: item.length,
    actualLength: item.fact.length,
    unicodeCharacterCount: [...item.fact].length,
    matches: item.length === item.fact.length,
}));

console.log("Fact length diagnostics:", diagnostics);

// 1. Status code
pm.test("Status code should be 200", function () {
    pm.response.to.have.status(200);
});

// 2. Response format
pm.test("Response should be JSON", function () {
    pm.response.to.be.json;
});

// 3. Data array
pm.test("Response should contain a non-empty data array", function () {
    pm.expect(jsonData.data).to.be.an("array").that.is.not.empty;
});

// 4. Requested limit
pm.test("Returned records should respect the requested limit", function () {
    pm.expect(jsonData.data.length).to.be.at.most(requestedLimit);
    pm.expect(jsonData.per_page).to.eql(requestedLimit);
});

// 5. Record validation
pm.test("Each record should contain valid fact data", function () {
    jsonData.data.forEach(function (item) {
        pm.expect(item.fact).to.be.a("string").and.not.be.empty;
        pm.expect(item.length).to.be.a("number");
    });
});

// 6. Data integrity
pm.test("Each fact length should match its actual text length", function () {
    jsonData.data.forEach(function (item, index) {
        pm.expect(
            item.length,
            `Length mismatch in record ${index + 1}: ${item.fact}`
        ).to.eql(item.fact.length);
    });
});

// 7. Maximum fact length
pm.test("Each fact should respect max_length", function () {
    jsonData.data.forEach(function (item) {
        pm.expect(item.fact.length).to.be.at.most(maxLength);
    });
});

// 8. Pagination metadata
pm.test("Pagination metadata should be valid", function () {
    pm.expect(jsonData.current_page).to.be.a("number").and.above(0);
    pm.expect(jsonData.last_page).to.be.a("number").and.above(0);
    pm.expect(jsonData.total).to.be.a("number").and.at.least(0);

    pm.expect(jsonData.current_page).to.be.at.most(jsonData.last_page);
});

// 9. First page navigation
pm.test("First page should have a next page but no previous page", function () {
    if (jsonData.current_page === 1) {
        pm.expect(jsonData.next_page_url).to.be.a("string");
        pm.expect(jsonData.prev_page_url).to.be.null;
    }
});

